// Title: Create a ZIP archive of all PNG worksheet page images rendered with Aspose.Cells in C#
// Common Searches: how to zip multiple worksheet page PNGs generated by Aspose.Cells using C# | Aspose.Cells render each sheet page to image and compress into a zip file in .NET | C# code to export Excel sheets as PNG images and bundle them into a zip archive | using System.IO.Compression to package Aspose.Cells rendered page images | clean up temporary folder after creating zip of Aspose.Cells image output
// Tags: Aspose.Cells render worksheet pages to PNG | C# create zip archive from directory | System.IO.Compression zip folder | export Excel sheets as images Aspose.Cells | temporary directory cleanup C#

using System;
using System.IO;
using System.IO.Compression;
using Aspose.Cells;
using Aspose.Cells.Rendering;

// The example creates a workbook, renders each worksheet page to PNG files with Aspose.Cells, saves them in a temporary folder, compresses the folder into a ZIP archive using System.IO.Compression, and then removes the temporary files.
class Program
{
    static void Main()
    {
        // Main execution wrapped in try-catch for safety
        try
        {
            // Create a new workbook and add sample data
            Workbook workbook = new Workbook();
            Worksheet sheet = workbook.Worksheets[0];
            sheet.Name = "SampleSheet";

            for (int i = 0; i < 100; i++)
            {
                sheet.Cells[i, 0].PutValue($"Row {i + 1}");
            }

            // Temporary folder to store individual image pages
            string tempFolder = Path.Combine(Path.GetTempPath(), "TiffPages_" + Guid.NewGuid().ToString("N"));
            Directory.CreateDirectory(tempFolder);

            // Render each worksheet to separate image files
            foreach (Worksheet ws in workbook.Worksheets)
            {
                // Configure image options for output
                ImageOrPrintOptions imgOptions = new ImageOrPrintOptions
                {
                    // Default format is PNG; if TIFF is required, ensure the library version supports ImageFormat property
                    // ImageFormat = ImageFormat.Tiff, // Uncomment if supported
                    OnePagePerSheet = false,               // Allow multiple pages per sheet
                    HorizontalResolution = 200,
                    VerticalResolution = 200,
                    Transparent = false
                };

                // Render the worksheet pages
                SheetRender sheetRender = new SheetRender(ws, imgOptions);
                int pageCount = sheetRender.PageCount;

                for (int pageIndex = 0; pageIndex < pageCount; pageIndex++)
                {
                    string fileName = $"{ws.Name}_Page{pageIndex + 1}.png"; // Using PNG extension
                    string filePath = Path.Combine(tempFolder, fileName);
                    sheetRender.ToImage(pageIndex, filePath);
                }
            }

            // Create ZIP archive containing all image files
            string zipPath = Path.Combine(Environment.CurrentDirectory, "WorkbookPages.zip");
            if (File.Exists(zipPath))
            {
                File.Delete(zipPath);
            }
            ZipFile.CreateFromDirectory(tempFolder, zipPath);

            Console.WriteLine($"ZIP archive created at: {zipPath}");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"An error occurred: {ex.Message}");
        }
        finally
        {
            // Clean up temporary files if they exist
            try
            {
                string tempRoot = Path.Combine(Path.GetTempPath(), "TiffPages_");
                var dirs = Directory.GetDirectories(Path.GetTempPath(), "TiffPages_*");
                foreach (var dir in dirs)
                {
                    if (Directory.Exists(dir))
                    {
                        Directory.Delete(dir, true);
                    }
                }
            }
            catch (Exception cleanupEx)
            {
                Console.WriteLine($"Cleanup error: {cleanupEx.Message}");
            }
        }
    }
}
